        negotiableLine: json["negotiable_line"],
        perSqftCarpetLabel: json["per_sqft_carpet_label"],
        rulesVersion: json["rules_version"],
        schema: json["schema"],
        vsQuotedLine: json["vs_quoted_line"],
        waived: json["waived"] == null ? null : List<String>.from(json["waived"]!.map((x) => x)),
