///plinth.doc_check/1, from api.doc_check(p_id) after the doc-check edge function
///(API_CONTRACTS §4.12; F-90, F-10, F-92, F-94, F-91). Nothing is checked before the buyer
///confirms the project. Verdicts come from rules, never from AI.
class DocCheck {
    final DocCheckActions? actions;
    final String? breakdownLine;
    
    ///kind = cost_sheet only.
    final CostBreakdownClass? cost;
    final String? docLabel;
    final String id;
    final String kind;
    final List<String> notes;
    
    ///kind = before_you_pay only.
    final PayeeResult? payee;
    final ProjectMatch? projectMatch;
    final List<DocCheckRow> rows;
    final String rulesVersion;
    final String schema;
    final String status;
    final String? summaryLine;

    DocCheck({
        required this.actions,
        required this.breakdownLine,
        this.cost,
        required this.docLabel,
        required this.id,
        required this.kind,
        required this.notes,
        this.payee,
        required this.projectMatch,
        required this.rows,
        required this.rulesVersion,
        required this.schema,
        required this.status,
        required this.summaryLine,
    });

