        required this.complaints,
        required this.confidence,
        required this.developerResponse,
        required this.display,
        required this.frequency,
        required this.late12,
        required this.meta,
        required this.pending,
        required this.phase,
        required this.price,
        required this.progress,
        required this.reasons,
        required this.schema,
        required this.share,
        required this.whatWouldChange,
        required this.withheld,
    });

    factory RiskSummary.fromJson(Map<String, dynamic> json) => RiskSummary(
        band: json["band"] == null ? null : Band.fromJson(json["band"]),
        chip: Chip.fromJson(json["chip"]),
        complaints: json["complaints"] == null ? null : Complaints.fromJson(json["complaints"]),
        confidence: json["confidence"] == null ? null : Confidence.fromJson(json["confidence"]),
        developerResponse: json["developer_response"] == null ? null : DeveloperResponse.fromJson(json["developer_response"]),
        display: Display.fromJson(json["display"]),
        frequency: json["frequency"] == null ? null : Frequency.fromJson(json["frequency"]),
        late12: Late12.fromJson(json["late12"]),
        meta: RiskMeta.fromJson(json["meta"]),
        pending: List<PendingFact>.from(json["pending"].map((x) => PendingFact.fromJson(x))),
        phase: PhaseSummary.fromJson(json["phase"]),
        price: json["price"] == null ? null : Price.fromJson(json["price"]),
        progress: Progress.fromJson(json["progress"]),
        reasons: List<Reason>.from(json["reasons"].map((x) => Reason.fromJson(x))),
        schema: json["schema"],
        share: RiskShare.fromJson(json["share"]),
